---
title: 1.1.2. Wat is het aantal cliënten met een Wlz-indicatie per leveringsvorm en zorgprofiel?
weight: 1
---
## Concepten
- [Leveringsvorm](http://purl.org/ozo/onz-zorg#Leveringsvorm)
- [Mens](http://purl.org/ozo/onz-g#Human)
- [Verpleegproces](http://purl.org/ozo/onz-zorg#NursingProcess)
- [Vestiging](http://purl.org/ozo/onz-org#Vestiging)
- [Vestigingsnummer](http://purl.org/ozo/onz-org#Vestigingsnummer)
- [Wlz-indicatie](http://purl.org/ozo/onz-zorg#WlzIndicatie)
- [Zorgprofiel](http://purl.org/ozo/onz-zorg#ZorgProfiel)
## Relaties
- [deel van](http://purl.org/ozo/onz-g#partOf)
- [gaat over](http://purl.org/ozo/onz-g#isAbout)
- [gedefinieerd door](http://purl.org/ozo/onz-g#definedBy)
- [geïdentificeerd door](http://purl.org/ozo/onz-g#identifiedBy)
- [heeft deel](http://purl.org/ozo/onz-g#hasPart)
- [heeft perdurantlocatie](http://purl.org/ozo/onz-g#hasPerdurantLocation)
## Eigenschappen
- [einddatum](http://purl.org/ozo/onz-g#eindDatum)
- [heeft datawaarde](http://purl.org/ozo/onz-g#hasDataValue)
- [indicatie behandeling](http://purl.org/ozo/onz-zorg#heeftIndicatieBehandeling)
- [startdatum](http://purl.org/ozo/onz-g#startDatum)
## Instanties
- [Modulair pakket thuis](http://purl.org/ozo/onz-zorg#mpt)
- [Persoonsgebonden budget](http://purl.org/ozo/onz-zorg#pgb)
- [Verblijf in een instelling](http://purl.org/ozo/onz-zorg#instelling)
- [Volledig pakket thuis](http://purl.org/ozo/onz-zorg#vpt)
## SPARQL query
```
# Indicator: IGJ 1.1.2
# Parameters: ?vestigingsnummer, ?peildatum 
# Ontologie: versie 3.0.0 of nieuwer

PREFIX onz-org: <http://purl.org/ozo/onz-org#>
PREFIX onz-g:   <http://purl.org/ozo/onz-g#>
PREFIX onz-pers:<http://purl.org/ozo/onz-pers#>
PREFIX xsd:     <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs:    <http://www.w3.org/2000/01/rdf-schema#>
PREFIX onz-zorg:<http://purl.org/ozo/onz-zorg#>

SELECT ?zorgprofiel
       (COUNT(DISTINCT ?client) AS ?Totaal)
       (SUM(?is_verblijf_met_behandeling) AS ?verblijf_met_behandeling)
       (SUM(?is_verblijf_zonder_behandeling) AS ?verblijf_zonder_behandeling)
       (SUM(?is_pgb) AS ?pgb)
       (SUM(?is_mpt) AS ?mpt)
       (SUM(?is_vpt) AS ?vpt)
       (SUM(?is_pgb_en_mpt) AS ?pgb_en_mpt)
WHERE {
  {
    {
      SELECT DISTINCT ?zorgprofiel
      WHERE {
        ?zorgprofiel a onz-zorg:ZorgProfiel .
      }
    }
    OPTIONAL {
      SELECT ?zorgprofiel ?client
             ?is_verblijf_met_behandeling ?is_verblijf_zonder_behandeling
             ?is_pgb ?is_mpt ?is_vpt ?is_pgb_en_mpt
      WHERE {
        {
          # ---------- PER ZORGPROFIEL × CLIENT (aggregeer eerst 'any' flags) ----------
          SELECT ?zorgprofiel ?client
                 (MAX(?heeft_instelling_met_behandeling) AS ?is_verblijf_met_behandeling)
                 (MAX(?heeft_instelling_zonder_behandeling) AS ?is_verblijf_zonder_behandeling)
                 (MAX(?heeft_pgb_alleen) AS ?is_pgb)
                 (MAX(?heeft_mpt_alleen) AS ?is_mpt)
                 (MAX(?heeft_vpt) AS ?is_vpt)
                 (MAX(xsd:integer(?heeft_pgb)) AS ?has_pgb_any)
                 (MAX(xsd:integer(?heeft_mpt)) AS ?has_mpt_any)
          WHERE {
            #BIND("2024-01-12"^^xsd:date AS ?peildatum)
            #BIND("000001254" AS ?target_vestigingsnummer)
            BIND(?peildatum AS ?peildatum_argument)

            # Vestiging en zorgproces binnen peildatum
            ?vestiging a onz-org:Vestiging ;
                       onz-g:identifiedBy ?vestigingsnummer_object .
            ?vestigingsnummer_object a onz-org:Vestigingsnummer ;
                                     onz-g:hasDataValue ?vestigingsnummer .
            #FILTER(?vestigingsnummer = ?target_vestigingsnummer)

            ?zorgproces a onz-zorg:NursingProcess ;
                        onz-g:definedBy ?indicatie ;
                        onz-g:hasPerdurantLocation/onz-g:partOf* ?vestiging ;
                        onz-g:startDatum ?start_zorgproces .
            OPTIONAL { ?zorgproces onz-g:eindDatum ?eind_zorgproces }
            FILTER(?peildatum_argument >= ?start_zorgproces &&
                   (?peildatum_argument <= ?eind_zorgproces || !BOUND(?eind_zorgproces)))

            # Indicatie binnen peildatum
            ?indicatie a onz-zorg:WlzIndicatie ;
                       onz-g:startDatum ?start_indicatie ;
                       onz-zorg:heeftIndicatieBehandeling ?behandeling ;
                       onz-g:isAbout ?client ;
                       onz-g:isAbout ?zorgproces ;
                       onz-g:hasPart ?leveringsvorm ;
                       onz-g:hasPart ?zorgprofiel .
            OPTIONAL { ?indicatie onz-g:eindDatum ?eind_indicatie }
            FILTER(?peildatum_argument >= ?start_indicatie &&
                   (?peildatum_argument <= ?eind_indicatie || !BOUND(?eind_indicatie)))

            ?leveringsvorm a onz-zorg:Leveringsvorm .
            ?zorgprofiel  a onz-zorg:ZorgProfiel .
            ?client a onz-g:Human .

            # Flags per indicatie
            BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:pgb }        AS ?heeft_pgb)
            BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:mpt }        AS ?heeft_mpt)
            BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:vpt }        AS ?heeft_vpt_check)
            BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:instelling } AS ?heeft_instelling)

            # Categorieën per indicatie
            BIND(IF(?leveringsvorm = onz-zorg:instelling && ?behandeling, 1, 0) AS ?heeft_instelling_met_behandeling)
            BIND(IF(?leveringsvorm = onz-zorg:instelling && !?behandeling, 1, 0) AS ?heeft_instelling_zonder_behandeling)
            BIND(IF(?heeft_pgb && !?heeft_mpt, 1, 0) AS ?heeft_pgb_alleen)
            BIND(IF(?heeft_mpt && !?heeft_pgb, 1, 0) AS ?heeft_mpt_alleen)
            BIND(IF(?heeft_vpt_check, 1, 0) AS ?heeft_vpt)
          }
          GROUP BY ?zorgprofiel ?client
        }
        # ---------- combinatie na aggregatie ----------
        BIND(IF(?has_pgb_any = 1 && ?has_mpt_any = 1, 1, 0) AS ?is_pgb_en_mpt)
      }
    }
  }
  UNION
  {
    VALUES ?zorgprofiel { "Totaal uniek aantal clienten" }
    OPTIONAL {
      {
        # ---------- Alle kolommen per cliënt (zoals eerder), zónder pgb_en_mpt ----------
        SELECT DISTINCT ?client
               ?is_verblijf_met_behandeling ?is_verblijf_zonder_behandeling
               ?is_pgb ?is_mpt ?is_vpt ?is_pgb_en_mpt
        WHERE {
          {
            SELECT ?client
                   (MAX(?heeft_instelling_met_behandeling) AS ?is_verblijf_met_behandeling)
                   (MAX(?heeft_instelling_zonder_behandeling) AS ?is_verblijf_zonder_behandeling)
                   (MAX(?heeft_pgb_alleen) AS ?is_pgb)
                   (MAX(?heeft_mpt_alleen) AS ?is_mpt)
                   (MAX(?heeft_vpt) AS ?is_vpt)
            WHERE {
              #BIND("2024-01-12"^^xsd:date AS ?peildatum)
              #BIND("000001254" AS ?target_vestigingsnummer)
              BIND(?peildatum AS ?peildatum_argument)

              ?vestiging a onz-org:Vestiging ;
                         onz-g:identifiedBy ?vestigingsnummer_object .
              ?vestigingsnummer_object a onz-org:Vestigingsnummer ;
                                       onz-g:hasDataValue ?vestigingsnummer .
              #FILTER(?vestigingsnummer = ?target_vestigingsnummer)

              ?zorgproces a onz-zorg:NursingProcess ;
                          onz-g:definedBy ?indicatie ;
                          onz-g:hasPerdurantLocation/onz-g:partOf* ?vestiging ;
                          onz-g:startDatum ?start_zorgproces .
              OPTIONAL { ?zorgproces onz-g:eindDatum ?eind_zorgproces }
              FILTER(?peildatum_argument >= ?start_zorgproces &&
                     (?peildatum_argument <= ?eind_zorgproces || !BOUND(?eind_zorgproces)))

              ?client a onz-g:Human .
              ?indicatie a onz-zorg:WlzIndicatie ;
                         onz-g:startDatum ?start_indicatie ;
                         onz-zorg:heeftIndicatieBehandeling ?behandeling ;
                         onz-g:isAbout ?client ;
                         onz-g:isAbout ?zorgproces ;
                         onz-g:hasPart ?leveringsvorm ;
                         onz-g:hasPart ?zorgprofiel_i .
              OPTIONAL { ?indicatie onz-g:eindDatum ?eind_indicatie }
              FILTER(?peildatum_argument >= ?start_indicatie &&
                     (?peildatum_argument <= ?eind_indicatie || !BOUND(?eind_indicatie)))

              ?leveringsvorm a onz-zorg:Leveringsvorm .
              ?zorgprofiel_i a onz-zorg:ZorgProfiel .

              # per-indicatie flags
              BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:pgb }        AS ?heeft_pgb)
              BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:mpt }        AS ?heeft_mpt)
              BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:vpt }        AS ?heeft_vpt_check)
              BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:instelling } AS ?heeft_instelling)

              BIND(IF(?leveringsvorm = onz-zorg:instelling && ?behandeling, 1, 0) AS ?heeft_instelling_met_behandeling)
              BIND(IF(?leveringsvorm = onz-zorg:instelling && !?behandeling, 1, 0) AS ?heeft_instelling_zonder_behandeling)
              BIND(IF(?heeft_pgb && !?heeft_mpt, 1, 0) AS ?heeft_pgb_alleen)
              BIND(IF(?heeft_mpt && !?heeft_pgb, 1, 0) AS ?heeft_mpt_alleen)
              BIND(IF(?heeft_vpt_check, 1, 0) AS ?heeft_vpt)
            }
            GROUP BY ?client
          }

          # ---------- Specifiek pgb_en_mpt: per client × zorgprofiel combineren, daarna per client ----------
          OPTIONAL {
            {
              SELECT ?client (MAX(?combo_zp) AS ?combo_any)
              WHERE {
                SELECT ?client ?zp
                       (MAX(xsd:integer(?heeft_pgb)) AS ?has_pgb_any_zp)
                       (MAX(xsd:integer(?heeft_mpt)) AS ?has_mpt_any_zp)
                       (IF( (MAX(xsd:integer(?heeft_pgb)) = 1) && (MAX(xsd:integer(?heeft_mpt)) = 1), 1, 0) AS ?combo_zp)
                WHERE {
                  #BIND("2024-01-12"^^xsd:date AS ?peildatum)
                  #BIND("000001254" AS ?target_vestigingsnummer)
                  BIND(?peildatum AS ?peildatum_argument)

                  ?vestiging a onz-org:Vestiging ;
                             onz-g:identifiedBy ?vestigingsnummer_object .
                  ?vestigingsnummer_object a onz-org:Vestigingsnummer ;
                                           onz-g:hasDataValue ?vestigingsnummer .
                  #FILTER(?vestigingsnummer = ?target_vestigingsnummer)

                  ?zorgproces a onz-zorg:NursingProcess ;
                              onz-g:definedBy ?indicatie ;
                              onz-g:hasPerdurantLocation/onz-g:partOf* ?vestiging ;
                              onz-g:startDatum ?start_zorgproces .
                  OPTIONAL { ?zorgproces onz-g:eindDatum ?eind_zorgproces }
                  FILTER(?peildatum_argument >= ?start_zorgproces &&
                         (?peildatum_argument <= ?eind_zorgproces || !BOUND(?eind_zorgproces)))

                  ?client a onz-g:Human .
                  ?indicatie a onz-zorg:WlzIndicatie ;
                             onz-g:startDatum ?start_indicatie ;
                             onz-g:isAbout ?client ;
                             onz-g:isAbout ?zorgproces ;
                             onz-g:hasPart ?lv ;
                             onz-g:hasPart ?zp .
                  OPTIONAL { ?indicatie onz-g:eindDatum ?eind_indicatie }
                  FILTER(?peildatum_argument >= ?start_indicatie &&
                         (?peildatum_argument <= ?eind_indicatie || !BOUND(?eind_indicatie)))

                  ?lv a onz-zorg:Leveringsvorm .
                  ?zp a onz-zorg:ZorgProfiel .

                  BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:pgb } AS ?heeft_pgb)
                  BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:mpt } AS ?heeft_mpt)
                }
                GROUP BY ?client ?zp
              }
              GROUP BY ?client
            }
            BIND(COALESCE(?combo_any, 0) AS ?is_pgb_en_mpt)
          }
        }
      }
    }
  }
}   
GROUP BY ?zorgprofiel
ORDER BY ?zorgprofiel

