                  ?client a onz-g:Human .
                  ?indicatie a onz-zorg:WlzIndicatie ;
                             onz-g:startDatum ?start_indicatie ;
                             onz-g:isAbout ?client ;
                             onz-g:isAbout ?zorgproces ;
                             onz-g:hasPart ?lv ;
                             onz-g:hasPart ?zp .
                  OPTIONAL { ?indicatie onz-g:eindDatum ?eind_indicatie }
                  FILTER(?peildatum_argument >= ?start_indicatie &&
                         (?peildatum_argument <= ?eind_indicatie || !BOUND(?eind_indicatie)))

                  ?lv a onz-zorg:Leveringsvorm .
                  ?zp a onz-zorg:ZorgProfiel .

                  BIND(EXISTS { ?indicatie onz-g:hasPart onz-zorg:pgb } AS ?heeft_pgb)
