# Indicator: IGJ 1.4.1
# Parameters: ?peildatum, ?vestigingsnummer
# Ontologie: versie 3.0.0 of nieuwer

PREFIX onz-g: <http://purl.org/ozo/onz-g#>
PREFIX onz-pers: <http://purl.org/ozo/onz-pers#>
PREFIX onz-zorg: <http://purl.org/ozo/onz-zorg#>
PREFIX onz-org: <http://purl.org/ozo/onz-org#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
    ?kwalificatieniveau
    (SUM(COALESCE(?dag_dienst * ?pil, 0)) AS ?Aantal_ZV_PIL_dag)
    (SUM(COALESCE(?avond_dienst * ?pil, 0)) AS ?Aantal_ZV_PIL_avond)
    (SUM(COALESCE(?nacht_dienst * ?pil, 0)) AS ?Aantal_ZV_PIL_nacht)
    (SUM(COALESCE(?dag_dienst * ?pnil, 0)) AS ?Aantal_ZV_PNIL_dag)
    (SUM(COALESCE(?avond_dienst * ?pnil, 0)) AS ?Aantal_ZV_PNIL_avond)
    (SUM(COALESCE(?nacht_dienst * ?pnil, 0)) AS ?Aantal_ZV_PNIL_nacht)
{
    # Dynamisch alleen Zorgverlenerfunctie kwalificatieniveaus ophalen
    {
        SELECT DISTINCT ?kwalificatieniveau {
            {
                ?functie
                    a onz-pers:ZorgverlenerFunctie ;
                    onz-g:hasQuality /onz-g:hasQualityValue ?functie_niveau .
                ?functie_niveau
                    a onz-pers:ODBKwalificatieWaarde ;
                    rdfs:label ?kwalificatieniveau .
            } UNION {
                BIND("Totaal" AS ?kwalificatieniveau)
            }
        }
    }

    # Optioneel de werkelijke data matchen
    OPTIONAL {
        {
            SELECT DISTINCT 
                ?medewerker
                ?kwalificatieniveau
                ?dag_dienst
                ?avond_dienst
                ?nacht_dienst
                ?pil
                ?pnil
            {
                # BIND ("2023-09-15"^^xsd:date AS ?peildatum)
                # BIND("000001254" AS ?vestigingsnummer)

                # Werkperiode van alle zorgverlener functies
                ?gewerkte_periode
                    a onz-pers:GewerktePeriode ;
                    onz-g:definedBy ?overeenkomst ;
                    onz-g:hasPerdurantLocation ?werk_locatie ;
                    onz-g:hasBeginTimeStamp ?start_werk .

                BIND(HOURS(?start_werk) AS ?start_uur)

                ?werk_locatie onz-g:partOf* ?vestiging . # vind Vestiging die hoort bij werk_locatie

                ?vestiging 
                    a onz-org:Vestiging ;
                    onz-g:identifiedBy ?vestigingsnummer_object .
                ?vestigingsnummer_object
                    a onz-org:Vestigingsnummer ;
                    onz-g:hasDataValue ?vestigingsnummer . # filter vestiging op gegeven vestigingsnummer

                # Datum filter zo vroeg mogelijk (zoals in 1.4.2)
                BIND(STRDT(SUBSTR(STR(?start_werk), 1, 10), xsd:date) AS ?start_werk_datum)

                # Filter op het 24-uurs DAN-tijdslot
                FILTER(
                    (?start_werk_datum = ?peildatum && ?start_uur >= 7) ||
                    (?start_werk_datum = (?peildatum + "P1D"^^xsd:duration) && ?start_uur < 7)
                )

                VALUES ?personeels_overeenkomst 
                { 
                    onz-pers:ArbeidsOvereenkomst
                    onz-pers:UitzendOvereenkomst
                    onz-pers:InhuurOvereenkomst
                }

                ?overeenkomst 
                    a ?personeels_overeenkomst ;
                    onz-pers:heeftOpdrachtnemer ?medewerker ;
                    onz-g:hasPart ?overeenkomst_afspraak .

                ?overeenkomst_afspraak
                    a onz-pers:WerkOvereenkomstAfspraak ;
                    onz-g:startDatum ?start_afspraak ;
                    onz-g:isAbout ?functie .

                OPTIONAL {?overeenkomst_afspraak onz-g:eindDatum ?eind_afspraak}
                FILTER (?start_afspraak <= ?peildatum && (!BOUND(?eind_afspraak) || ?eind_afspraak >= ?peildatum))

                ?functie
                    a onz-pers:ZorgverlenerFunctie ;
                    onz-g:hasQuality /onz-g:hasQualityValue ?functie_niveau .

                ?functie_niveau
                    a onz-pers:ODBKwalificatieWaarde .
                {
                    ?functie_niveau
                        a onz-pers:ODBKwalificatieWaarde ;
                        rdfs:label ?kwalificatieniveau .
                } UNION {
                    BIND("Totaal" AS ?kwalificatieniveau ) 
                }

                BIND(IF(?start_uur >= 7 && ?start_uur < 15, 1, 0) AS ?dag_dienst)
                BIND(IF(?start_uur >= 15 && ?start_uur < 23, 1, 0) AS ?avond_dienst)
                BIND(IF(?start_uur >= 23 || ?start_uur < 7, 1, 0) AS ?nacht_dienst)
                BIND(IF (?personeels_overeenkomst = onz-pers:ArbeidsOvereenkomst, 1, 0) AS ?pil)
                BIND(IF (?pil = 0, 1, 0) AS ?pnil)
            }
        }
    }
}
GROUP BY ?kwalificatieniveau
ORDER BY ?kwalificatieniveau

