@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix schema: <http://schema.org/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix dash: <http://datashapes.org/dash#> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix vcard: <http://www.w3.org/2006/vcard/ns#> .
@prefix ex: <http://example.com/> .

#------------------------------------------------------------------------------------------------------------------------
# "De volgende SHACL shapes definieren de invoerparameters voor de SPARQL-query's..
# Alle parameters zijn opgenomen in dit bestand; de parameters zijn ook afzonderlijk in aanvullende bestanden opgenomen.
# De 'min' en 'max' waarden voor de parameterwaarden zijn willekeurig geselecteerd. Ze moeten nog als juiste waarde worden ingesteld.
#------------------------------------------------------------------------------------------------------------------------


# Parameter-shapes voor peildatum met handmatige invoer als een datum.
ex:PeilDatumManualEntry
    a sh:NodeShape ;
    sh:targetClass ex:PeilDatumManualEntry ;
    rdfs:label "Peildatum zonder keuzelijst";
    rdfs:comment "Een shape voor het creeren van een handmatig invoerveld waarmee de gebruiker de peildatum kan specificeren.."@nl ;
    sh:property [
          sh:path ex:peildatum ;
          sh:name "peildatum";
          sh:description "Handmatige invoer van peildatumwaarden."@nl ;
          sh:maxCount 1 ;
          sh:minCount 1 ;
          sh:datatype xsd:date ;
          sh:maxInclusive "2029-12-31"^^xsd:date ;
          sh:minInclusive "2020-12-31"^^xsd:date ;
      ]
.


# De volgende SHACL shape definieert de invoerparameter voor Vestigingsnummer met handmatige invoer als een string..
ex:VestigingsnummerManualEntry
    a sh:NodeShape ;
    sh:targetClass ex:VestigingsnummerManualEntry ;
    rdfs:label "Vestigingsnummer voor handmatige invoer";
    rdfs:comment "Een shape voor het creeren van een handmatig invoerveld waarmee de gebruiker het KvK Vestigingsnummer kan specificeren."@nl ;
    sh:property [
          sh:path ex:vestigingsnummer ;
          sh:name "vestigingsnummer";
          sh:description "Handmatige invoer van het KvK vestigingsnummer."@nl ;
          sh:maxCount 1 ;
          sh:minCount 1 ;
          sh:datatype xsd:string ;  
          sh:pattern "^[0-9]{12}$" ; 
    ]        
.

binds.expression:
IF(?is_next_day_early, 31.0,                                   # eindigt uiterlijk bij DAN-einde
                        IF(?eind_uur_exact < ?start_uur_exact, ?eind_uur_exact + 24.0, ?eind_uur_exact)
                    )

